import json, time, urllib.request, urllib.error, collections, sys
BASE = "http://localhost:8080"
token = None
stats = collections.Counter()

def new_token():
    global token
    req = urllib.request.Request(BASE + "/token", method="POST", data=b"")
    with urllib.request.urlopen(req) as r:
        token = json.load(r)["token"]
    stats["token_fetches"] += 1

def get(path):
    for attempt in range(200):
        if token is None:
            new_token()
        req = urllib.request.Request(BASE + path, headers={"Authorization": f"Bearer {token}"})
        try:
            with urllib.request.urlopen(req, timeout=30) as r:
                body = r.read()
                stats["200"] += 1
                return 200, json.loads(body)
        except urllib.error.HTTPError as e:
            body = e.read()
            stats[str(e.code)] += 1
            if e.code == 401:
                new_token(); continue
            if e.code == 429:
                ra = e.headers.get("Retry-After")
                try: wait = float(ra)
                except (TypeError, ValueError):
                    try: wait = float(json.loads(body).get("retry_after", 1))
                    except Exception: wait = 1
                time.sleep(wait); continue
            if e.code == 404:
                return 404, body.decode(errors="replace")
            print(f"HTTP {e.code} on {path}: {body[:200]!r}", file=sys.stderr)
            time.sleep(0.5); continue
        except (urllib.error.URLError, ConnectionError, TimeoutError, json.JSONDecodeError) as e:
            stats["neterr"] += 1
            print(f"error on {path}: {e!r}", file=sys.stderr)
            time.sleep(0.5); continue
    raise RuntimeError(f"gave up on {path}")

pages = {}
path = "/orders?page=1"
while path:
    code, data = get(path)
    assert code == 200, (path, code, data)
    pages[data["page"]] = data
    path = data["next"]
total_pages = pages[1]["total_pages"]
print("pages fetched:", sorted(pages), "total_pages:", total_pages, file=sys.stderr)
missing = [p for p in range(1, total_pages + 1) if p not in pages]
for p in missing:
    code, data = get(f"/orders?page={p}"); assert code == 200; pages[p] = data

listings = [it for p in sorted(pages) for it in pages[p]["items"]]
cust_ids = sorted({it["customer_id"] for it in listings})
customers = {}
for cid in cust_ids:
    code, data = get(f"/customers/{cid}")
    customers[cid] = data if code == 200 else None
json.dump({"pages": pages, "customers": customers, "stats": stats}, open("/tmp/recon/raw.json", "w"))
print(dict(stats), file=sys.stderr)
EOF
python3 -I /tmp/recon/fetch.py

